-- Adds official night-order data to characters: which position each wakes
-- at on the first night vs subsequent nights, and the Storyteller's
-- reminder-card text for that wake, so the script detail page can render
-- a real "First night" / "Other nights" run sheet (matching what
-- botcscripts.com already shows) instead of the fixed "doesn't override
-- the night order" placeholder message it had before.
--
-- 0 = this character is known not to wake on that night (e.g. most
-- Townsfolk have other_night = 0). null = no data yet for this character
-- (see the backfill note below) — the app must treat these differently:
-- 0 means "correctly omit", null means "we don't know, say so".
alter table public.characters
  add column first_night smallint,
  add column first_night_reminder text,
  add column other_night smallint,
  add column other_night_reminder text;

-- Backfills official first/other-night wake order + reminder-card text for
-- the 130 characters sourced from bra1n/townsquare's roles.json (same
-- MIT-licensed source already used for ability text and the Phase 2
-- follow-up #2 character-library backfill). The 27 newer Carousel/
-- Experimental-pool characters that repo has never added (Kazali, Lord of
-- Typhon, Ojo, Yaggababble, and 23 others — see the Phase 2 follow-up #3
-- migration for the full list) are deliberately left null here rather than
-- guessed at; the app treats null as "no data yet" and shows an honest
-- note instead of a fabricated position.
update public.characters as c
set first_night = v.first_night,
    first_night_reminder = nullif(v.first_night_reminder, ''),
    other_night = v.other_night,
    other_night_reminder = nullif(v.other_night_reminder, '')
